/** FIPS code → index into COUNTIES for fast lookup */
export const FIPS_INDEX: Map<string, number> = new Map(
  COUNTIES.map((c, i) => [c.fips, i])
);

/** Lowercase "county|state" → index for name-based lookup */
export const NAME_INDEX: Map<string, number> = new Map(
  COUNTIES.map((c, i) => [`${c.county.toLowerCase()}|${c.state.toLowerCase()}`, i])
);

/** Lowercase county name → indices (for lookup without state) */
export const COUNTY_NAME_INDEX: Map<string, number[]> = new Map();
COUNTIES.forEach((c, i) => {
  const key = c.county.toLowerCase();
  const arr = COUNTY_NAME_INDEX.get(key) ?? [];
  arr.push(i);
  COUNTY_NAME_INDEX.set(key, arr);
});
